// SyncKeys brings an existing table's keys up to date (table sync at startup): creates
// missing indexes and builds, rebuilds or drops the SIFT totals of keys with
// sum_index_fields (sift.Sync; unchanged keys cost one query).
func (t *FADepreciationBook) SyncKeys(db database.Executor, company string, dbType database.DBType) error {
	tableName := fmt.Sprintf("%s$%s", company, FADepreciationBookTableName)
	siftCompany := company
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (fa_no, depreciation_book_code)`,
		fmt.Sprintf("%s$FA_Depreciation_Book$Primary", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index Primary: %w", err)
	}
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (depreciation_book_code, fa_no)`,
		fmt.Sprintf("%s$FA_Depreciation_Book$book_fa", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index book_fa: %w", err)
	}
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (depreciation_book_code, component_of_main_asset, main_asset_component)`,
		fmt.Sprintf("%s$FA_Depreciation_Book$book_main_asset", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index book_main_asset: %w", err)
	}
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (main_asset_component, depreciation_book_code)`,
		fmt.Sprintf("%s$FA_Depreciation_Book$main_asset_book", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index main_asset_book: %w", err)
	}
	var keys []sift.Key
	for _, spec := range fADepreciationBookSIFTSpecs() {
		keys = append(keys, sift.BuildKey(dbType, siftCompany, FADepreciationBookTableName, tableName, spec))
	}
	return sift.Sync(db, dbType, siftCompany, FADepreciationBookTableName, keys)
}

// fADepreciationBookSIFTSpecs are the table's keys with sum_index_fields
func fADepreciationBookSIFTSpecs() []sift.KeySpec {
	return []sift.KeySpec{}
}

// VerifySIFT compares the table's SIFT totals with its entries (Verify SIFT codeunit); with
// repair it rebuilds the keys whose totals differ.
func (t *FADepreciationBook) VerifySIFT(repair bool) ([]sift.VerifyResult, error) {
	tableName, siftCompany := fmt.Sprintf("%s$%s", t.company, FADepreciationBookTableName), t.company
	var results []sift.VerifyResult
	for _, spec := range fADepreciationBookSIFTSpecs() {
		n, err := sift.VerifyKey(t.db, t.dbType, siftCompany, FADepreciationBookTableName, tableName, spec)
		if err != nil {
			return results, fmt.Errorf("%s: %w", spec.Name, err)
		}
		result := sift.VerifyResult{Table: FADepreciationBookTableName, Key: spec.Name, Differences: n}
		if n > 0 && repair {
			if err := sift.RebuildKey(t.db, t.dbType, siftCompany, FADepreciationBookTableName, tableName, spec); err != nil {
				return results, fmt.Errorf("%s: %w", spec.Name, err)
			}
			result.Rebuilt = true
		}
		results = append(results, result)
	}
	return results, nil
}

