// SetFlowFilter sets a FlowFilter field's filter expression (SETFILTER on a
// FlowFilter field); FlowFields applying it use it from then on. "" clears it.
func (t *FADepreciationBook) SetFlowFilter(field, expr string) error {
	switch field {
	case "maintenance_code_filter":
		if err := flowfilter.Validate(flowfilter.KindCode, expr); err != nil {
			return err
		}
		t.Maintenance_code_filter = expr
		return nil
	case "fa_posting_date_filter":
		if err := flowfilter.Validate(flowfilter.KindDate, expr); err != nil {
			return err
		}
		t.Fa_posting_date_filter = expr
		return nil
	}
	return fmt.Errorf("%q is not a FlowFilter field of FA_Depreciation_Book", field)
}

// GetFlowFilterFields returns the FlowFilter fields (name and flowfilter kind)
func (t *FADepreciationBook) GetFlowFilterFields() []tables.FlowFilterFieldInfo {
	return []tables.FlowFilterFieldInfo{
		{Name: "maintenance_code_filter", Kind: string(flowfilter.KindCode)},
		{Name: "fa_posting_date_filter", Kind: string(flowfilter.KindDate)},
	}
}

